+          <header class="site-header">
+            <a class="brand" href="#" aria-label="Luma Library home">
+              <span class="brand-mark" aria-hidden="true">L</span>
+              <span>Luma Library</span>
+            </a>
+            <nav class="top-nav" aria-label="Primary navigation">
+              <ul>
+                <li><a href="#">Library</a></li>
+                <li><a href="#" aria-current="page">Preview</a></li>
+                <li><a href="#">Shared</a></li>
+              </ul>
+            </nav>
+          </header>
+        `;
+      }
+
+      function ImagePreview({ item }) {
+        return `
+          <section class="image-card card" aria-labelledby="image-title">
+            <figure class="image-frame">
+              <img class="preview-image" src="${item.src}" alt="${item.alt}">
+              <figcaption class="image-caption">
+                <div>
+                  <p class="eyebrow">${item.collection}</p>
+                  <h1 id="image-title">${item.title}</h1>
+                  <p class="subtitle">
+                    Review the details of this image before making changes to your library.
+                  </p>
+                </div>
+                <a class="button button-secondary" href="#" download>Download</a>
+              </figcaption>
+            </figure>
+          </section>
+        `;
+      }
+
+      function DetailsPanel({ item }) {
+        return `
+          <aside class="meta-panel card" aria-labelledby="details-title">
+            <h2 id="details-title">Image details</h2>
+            <dl class="meta-list">
+              <div class="meta-row">
+                <dt>Collection</dt>
+                <dd>${item.collection}</dd>
+              </div>
+              <div class="meta-row">
+                <dt>Uploaded</dt>
+                <dd>${item.uploaded}</dd>
+              </div>
+              <div class="meta-row">
+                <dt>Size</dt>
+                <dd>${item.size}</dd>
+              </div>
+              <div class="meta-row">
+                <dt>Dimensions</dt>
+                <dd>${item.dimensions}</dd>
+              </div>
+            </dl>
+            <div class="actions">
+              <button class="button button-danger trigger" type="button" aria-haspopup="dialog">
+                Delete image
+              </button>
+              <button class="button button-secondary" type="button">Edit details</button>
+            </div>
+            <p class="status-message" aria-live="polite"></p>
+          </aside>
+        `;
+      }
+
+      function DeleteDialog({ item }) {
+        return `
+          <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
+            <div class="dialog-card">
+              <div class="dialog-icon" aria-hidden="true">!</div>
+              <h2 class="dialog-title" id="dialog-title">Delete image?</h2>
+              <p class="dialog-description" id="dialog-description">
+                This will permanently delete "${item.title}" from your library. This action cannot be undone.
+              </p>
+              <div class="dialog-actions">
+                <button class="button button-secondary" type="button" data-close-dialog>
+                  Cancel
+                </button>
+                <button class="button button-danger" type="button" data-confirm-delete>
+                  Delete image
+                </button>
+              </div>
+            </div>
+          </dialog>
+        `;
+      }
+
+      function App({ item }) {
+        return `
+          <div class="app-shell">
+            ${Header()}
+            <main id="main-content" tabindex="-1">
+              <div class="preview-layout">
+                ${ImagePreview({ item })}
+                ${DetailsPanel({ item })}
+              </div>
+            </main>
+          </div>
+          ${DeleteDialog({ item })}
+        `;
+      }
+
+      function setupDeleteDialog() {
+        const dialog = document.querySelector("#delete-dialog");
+        const trigger = document.querySelector(".trigger");
+        const closeButton = document.querySelector("[data-close-dialog]");
+        const confirmButton = document.querySelector("[data-confirm-delete]");
+        const statusMessage = document.querySelector(".status-message");
+        let returnFocusTo = null;
+
+        trigger.addEventListener("click", () => {
+          returnFocusTo = document.activeElement;
+          dialog.showModal();
+          closeButton.focus();
+        });
+
+        closeButton.addEventListener("click", () => {
+          dialog.close("cancel");
+        });
+
+        confirmButton.addEventListener("click", () => {
+          statusMessage.textContent = "Image deleted from your library.";
+          dialog.close("delete");
+        });
+
+        dialog.addEventListener("click", (event) => {
+          if (event.target === dialog) {
+            dialog.close("cancel");
+          }
+        });
+
+        dialog.addEventListener("close", () => {
+          if (returnFocusTo && typeof returnFocusTo.focus === "function") {
+            returnFocusTo.focus();
+          }
+        });
+      }
+
+      document.querySelector("#root").innerHTML = App({ item: image });
+      setupDeleteDialog();
+    </script>
+  </body>
+</html>
+

')

