    <style>
      :root {
        color-scheme: light;
        --bg: #f6f8fb;
        --surface: #ffffff;
        --surface-muted: #eef2f7;
        --text: #172033;
        --muted: #596579;
        --border: #c8d0dc;
        --primary: #2457d6;
        --primary-hover: #1d46ac;
        --danger: #b42318;
        --danger-hover: #8f1d14;
        --focus: #111827;
        --shadow: 0 24px 70px #17203333;
        --radius-lg: 28px;
        --radius-md: 18px;
        --radius-sm: 12px;
      }

