        color: var(--text);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--text);
        color: var(--surface);
        padding: 0.7rem 1rem;
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      a,
      button {
        font: inherit;
      }

      :focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--focus);
      }

      .app-shell {
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 1rem 0 3rem;
      }

      .site-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1rem 0 2.25rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.7rem;
        color: var(--text);
        font-weight: 800;
        letter-spacing: -0.03em;
        text-decoration: none;
      }

      .brand-mark {
        display: grid;
        width: 2.5rem;
