        padding: 0.65rem 0.9rem;
        font-weight: 700;
        text-decoration: none;
      }

      .top-nav a[aria-current="page"] {
        background: var(--surface);
        color: var(--text);
        box-shadow: 0 1px 0 var(--border);
      }

