        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1.25rem;
      }

      .eyebrow {
        margin: 0 0 0.35rem;
        color: var(--primary);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.12em;
