      }

      .meta-panel h2 {
        margin: 0 0 1rem;
        font-size: 1.1rem;
      }

      .meta-list {
        display: grid;
        gap: 0.9rem;
        margin: 0;
      }

      .meta-row {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        border-bottom: 1px solid var(--surface-muted);
        padding-bottom: 0.9rem;
      }

      .meta-row:last-child {
        border-bottom: 0;
        padding-bottom: 0;
      }

      .meta-row dt {
        color: var(--muted);
        font-weight: 700;
      }

      .meta-row dd {
        margin: 0;
        color: var(--text);
        font-weight: 800;
        text-align: right;
      }

      .image-actions,
      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      .actions {
        margin-top: 1.25rem;
      }

      .button {
        display: inline-flex;
        min-height: 2.85rem;
        align-items: center;
        justify-content: center;
        border: 1px solid transparent;
        border-radius: 999px;
        padding: 0.7rem 1.05rem;
        cursor: pointer;
        font-weight: 800;
        text-decoration: none;
      }

      .button-primary {
        background: var(--primary);
        color: #ffffff;
      }

      .button-primary:hover {
        background: var(--primary-hover);
      }

      .button-secondary {
        border-color: var(--border);
        background: var(--surface);
        color: var(--text);
      }

      .button-secondary:hover {
        background: var(--surface-muted);
      }

      .button-danger {
        background: var(--danger);
        color: #ffffff;
      }

      .button-danger:hover {
        background: var(--danger-hover);
      }

      .status-message {
        min-height: 1.5rem;
        margin-top: 1rem;
        color: var(--muted);
        font-weight: 700;
      }

      dialog {
        width: min(92vw, 31rem);
        border: 0;
        border-radius: var(--radius-lg);
        padding: 0;
        background: transparent;
        color: inherit;
      }

      dialog::backdrop {
        background: #111827b8;
        backdrop-filter: blur(5px);
      }

      .dialog-card {
        border: 1px solid var(--border);
        border-radius: var(--radius-lg);
        background: var(--surface);
        box-shadow: var(--shadow);
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        place-items: center;
        border-radius: 1rem;
        background: #fee4e2;
        color: var(--danger);
        font-size: 1.5rem;
        font-weight: 900;
      }

      .dialog-title {
        margin: 1rem 0 0.5rem;
        font-size: clamp(1.5rem, 7vw, 2rem);
        line-height: 1.1;
        letter-spacing: -0.04em;
      }

      .dialog-description {
        margin: 0;
        color: var(--muted);
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap-reverse;
        gap: 0.75rem;
        justify-content: flex-end;
        margin-top: 1.5rem;
      }

      @media (max-width: 760px) {
        .site-header,
        .preview-layout {
          display: block;
        }

        .top-nav {
          margin-top: 1rem;
        }

        .top-nav ul {
          flex-wrap: wrap;
        }

        .meta-panel {
          margin-top: 1rem;
